const entrada = $input.first().json;
const body = entrada.body ?? entrada;
const valor = body.entry?.[0]?.changes?.[0]?.value ?? {};
const contato = valor.contacts?.[0] ?? {};
const mensagemWhatsApp = valor.messages?.[0] ?? {};

const telefone = body.telefone ?? mensagemWhatsApp.from ?? '';
const nome = body.nome ?? contato.profile?.name ?? telefone ?? 'Sem nome';
const mensagem = body.mensagem
  ?? mensagemWhatsApp.text?.body
  ?? mensagemWhatsApp.button?.text
  ?? mensagemWhatsApp.interactive?.button_reply?.title
  ?? mensagemWhatsApp.interactive?.list_reply?.title
  ?? '';

if (!telefone || !mensagem) {
  throw new Error('O webhook precisa receber telefone e mensagem.');
}

const timestamp = mensagemWhatsApp.timestamp
  ? new Date(Number(mensagemWhatsApp.timestamp) * 1000).toISOString()
  : new Date().toISOString();

return [{
  json: {
    data_hora: timestamp,
    telefone: String(telefone),
    nome: String(nome),
    mensagem: String(mensagem),
    origem: body.entry ? 'whatsapp_cloud_api' : 'webhook_simulado',
    status: 'recebido',
    resposta: `Ola, ${nome}! Sua mensagem foi recebida.`,
    id_mensagem: body.id_mensagem ?? mensagemWhatsApp.id
  }
}];
